// === Tab: mySketch ===
let img;

let layer1, layer2;

let circles = [];


let colors = [
	["#1B1F3B", "#FEE1C7", "#FA7E61", "#F44174"],
	["#E2F1FF", "#4BB3FD", "#0496FF", "#027BCE"],
	["#141414", "#E0FBFC", "#C2DFE3", "#9DB4C0"],
	["#F1E4F3", "#F4BBD3", "#F686BD", "#34CA85"],
	["#F8E8E3", "#62D9FF", "#83C5BE", "#006D77"],
	["#241623", "#DA2C38", "#226F54", "#87C38F"],
	["#90A955", "#4F772D", "#31572C", "#C73A15"]
];

let mainColor, circleColor;

const maxRadius = 30;

let x, y, i = 0,
	r = 1;

let count = 0;

function preload() {
	img = loadImage("https://openprocessing.org/sketch/2134739/files/2024_image04.png");
}

function setup() {
	let minWindow = max(windowWidth, windowHeight);
	let SizeW = minWindow / max(img.width, img.height);
	createCanvas(minWindow, minWindow);
	layer1 = createGraphics(width, height);
	layer2 = createGraphics(width, height);
	mainColor = random(colors);
	layer2.background(mainColor[0]);
	layer1.background(255);
	circleColor = [mainColor[1], mainColor[2], mainColor[3]];
	layer2.noStroke();
	angleMode(DEGREES);
	layer1.image(img, width / 2 - img.width * SizeW / 2, height / 2 - img.height * SizeW / 2, img.width * SizeW, img.height * SizeW);
}

function draw() {
	count++;
	if (count < 200) {
		for (let k = 0; k < 7; k++) {
			do {
				x = random(width);
				y = random(height);
				i++;
				if (i > 1000) {
					return;
				}
			} while (!check(x, y, r) || !imgCheck(x, y, r));
			while (r < maxRadius && check(x, y, r) && imgCheck(x, y, r)) {
				r++;
			}
			r--;

			layer2.fill(random(circleColor));
			layer2.circle(x, y, r * 2);
			circles.push({
				x,
				y,
				r
			})

			r = 1;
			i = 0;
		}
		image(layer2, 0, 0);
	} else if (count == 1000) print("Done!");
}

function check(x, y, r) {
	let ok = true;
	circles.forEach((c) => {
		if (dist(x, y, c.x, c.y) < r + c.r) {
			ok = false;
		}
	});

	return ok;
}

function imgCheck(x, y, r) {
	var ok = true;
	for (let i = 0; i < 100; i++) {
		let c = layer1.get(x + r * cos((360 / 100) * i), y + r * sin((360 / 100) * i));
		if (c[0] > 10) {
			ok = false;
			break;
		}
	}

	return ok;
}

function keyPressed() {
	if (keyCode === 32) {
		mainColor = [];
		mainColor = random(colors);
		layer2.background(mainColor[0]);
		circleColor = [mainColor[1], mainColor[2], mainColor[3]];
		circles = [];
		count = 0;
	} else if (keyCode === 83) {
		saveCanvas();
	}
}

